/**
 * The browser-safe API contract (`lib/api/contract.ts`, generated by `bun run api:contract`) must
 * describe exactly the routes the server registry dispatches. `tsc` already checks the key set and the
 * method/path literals; this compares every field at runtime, `multipart`/`rawBlob` included.
 *
 * Imports the server registry under Bun (no dev server, no DB access, no env file needed).
 */
import { expect, test } from "bun:test";
import { APIEndpoints } from "@lib/api/contract";
import { routeEntries } from "@lib/api/routes";
import { API } from "@routes/index.client";

test("the generated contract matches the server route registry field for field", () => {
	const fromRegistry = Object.fromEntries(
		routeEntries().map(([endpoint, route]) => [endpoint, { method: route.method, path: route.path, multipart: route.multipart, rawBlob: route.rawBlob }]),
	);
	const contract: Record<string, unknown> = APIEndpoints;
	expect(contract).toStrictEqual(fromRegistry);
	// Same order too, so the committed file only changes where a route changed.
	expect(Object.keys(contract)).toEqual(Object.keys(fromRegistry));
});

test("API maps every group.name to its endpoint key", () => {
	const keys = Object.entries(API).flatMap(([group, names]) =>
		Object.entries(names as Record<string, string>).map(([name, endpoint]) => {
			expect(endpoint).toBe(`${group}.${name}`);
			return endpoint;
		}),
	);
	expect(keys.sort()).toEqual(Object.keys(APIEndpoints).sort());
});
